    workers=[d.read(p) for p in sorted((d.OUT/'workers').glob('*.json'))];assert all(x.get('actual_process_wait_returned') for x in workers);assert all(x['exit_code'] in (0,75) for x in workers)
    hours=sum(x['elapsed_seconds'] for x in workers)/3600;assert hours<=18
    counts=collections.Counter();byphase={}
    for path in (d.OUT/'calls').glob('*.jsonl'):
        for line in path.read_text().splitlines():
            r=d.json.loads(line);phase=r['phase'];byphase.setdefault(phase,collections.Counter())
            for k in ('native','raster','source_formations','query_encoder','attempted_updates','discarded_updates'):
                if k in r:counts[k]+=r[k];byphase[phase][k]+=r[k]
    assert byphase['formal']['attempted_updates']==36000 and byphase['training']['native']==72000 and byphase['evaluation_query']['native']==12672 and byphase['evaluation_formation']['source_formations']==792
    assert counts['discarded_updates']==6
    discarded=[]
    for folder in (d.OUT/'fits').iterdir():
        for p in folder.glob('discarded_*.jsonl'):discarded.extend(d.json.loads(s) for s in p.read_text().splitlines())
    assert not discarded,'All unexpected discarded work requires explicit reconciliation, not hidden extra work'
    ledger=[d.json.loads(s) for s in (d.OUT/'resources.jsonl').read_text().splitlines()];disk=d.bytes_used(d.CACHE);ram=d.bytes_used(d.RAM)
    assert ram==0,'Only retire owned resumes after all finals verified; no permanent result in RAM'
    # Atomic replacement temporary snapshot can peak between10-second samples.
    full_snapshot=max(r['restore']['bytes'] for r in d.read(d.OUT/'preflight.json')['records'] if r['restore']);events=[]
    import datetime
    for w in workers:
        begin=datetime.datetime.fromisoformat(w['started_utc']).timestamp();end=datetime.datetime.fromisoformat(w['ended_utc']).timestamp();events.extend([(begin,1),(end,-1)])
    running=0;max_running=0
    for _,delta in sorted(events):running+=delta;max_running=max(max_running,running)
    assert max_running<=5
    final_max=max(d.final(a,s).stat().st_size for a in d.ARMS for s in d.SEEDS)
    # Disk already contains all18permanent native weights. Replace each of up
    # to5allocated final weight envelopes by its full model+Adam resume, and
    # reserve one globally serialized atomic replacement. This avoids adding
    # the same sampled atomic temporary twice to an already-inclusive peak.
    overlap_upper=disk+max_running*(full_snapshot-final_max)+full_snapshot+2**20
    peak=max(max(r['DATA_bytes'] for r in ledger),overlap_upper)
    assert peak<=80*2**30,(peak/2**30)
    before=d.read(d.OUT/'living_docs_before.json');growth=sum(max(0,(d.ROOT/p).stat().st_size-v['bytes']) for p,v in before.items());project=d.bytes_used(d.OUT)+sum(p.stat().st_size for p in (d.ROOT/'experiments').glob('native_task_writer*'))+(d.ROOT/'models/native_task_writer.py').stat().st_size+growth
    assert project+10*2**20<=2**30
    obj=dict(complete=True,GPU_worker_hours=hours,GPU_limit_hours=18,workers=workers,calls=dict(counts),calls_by_phase={k:dict(v) for k,v in byphase.items()},formal_updates=36000,formal_samples=72000,discarded_preflight_updates=6,discarded_formal_updates=len(discarded),evaluation_predictions=12672,permanent_source_states=792,inherited_unique_Native=704,inherited_Local_Render=4224,DATA_root=str(d.CACHE),DATA_allocated_bytes=disk,owned_RAM_recovery_bytes=ram,DATA_peak_conservative_bytes=peak,peak_policy='Maximum of sampled owned DATA+RAM and complete permanent artifacts plus up to5full-Adam-minus-final-weight envelopes plus one serialized full atomic replacement and1MiBmetadata. Atomic samples not double-counted; owned RAM included.',peak_overlap_upper_bytes=overlap_upper,maximum_simultaneous_own_workers=max_running,project_upper_bytes=project+10*2**20,all_own_GPU_children_waited=True,all_final_weights_persistent=True,checkpoint_durability='Active exact resumes used owned RAM after measured disk bottleneck; process-interruption recovery, not host-reboot durability. All18final weights and792fields plus predictions permanent on DATA.',startup_failure_references=['results/gaussian_memory/autonomous_research_loop/round_015'],new_science_round=False,new_confirmation=False)
    d.write(d.OUT/'budget_actual.json',obj);return obj

