    d.write(d.OUT/'input_manifest.json',dict(source_authority=str(d.ROOT/'results/gaussian_memory/camera_only_feature_pe1/input_manifest.json'),authority_sha256=d.sha(d.ROOT/'results/gaussian_memory/camera_only_feature_pe1/input_manifest.json'),pretrained_model=inherited.get('pretrained_model'),source_input_identities=[d.read(p) for p in sorted((d.OUT/'formation').glob('*.json'))],query_input_identity_authority='evaluation/*.json, each actual query/patch SHA at publication',source_indices=[0,3,6,9],fit_queries=[2,5,8,11],other_queries=[1,4,7,10],old_DATA_not_fresh=True,raw_source_dependency_identities=inherited))
